#!/usr/bin/env python3
"""
Evaluate agent responses against the answer key.
This script helps candidates understand how well their agent is performing.
"""

import json
import argparse
from pathlib import Path
from typing import Dict, List, Tuple
from datetime import datetime
import re


def load_answer_key(path: str = "answer_key.json") -> Dict:
    """Load the answer key with expected behaviors."""
    with open(path, 'r') as f:
        return json.load(f)


def load_test_results(path: str) -> Dict:
    """Load test results generated by generate_test_data.py."""
    with open(path, 'r') as f:
        return json.load(f)


def evaluate_tools_usage(actual_tools: List[str], expected: Dict) -> Tuple[float, List[str]]:
    """
    Evaluate if the correct tools were used.

    Returns:
        Tuple of (score, list of issues)
    """
    issues = []
    score = 100.0

    required_tools = set(expected.get("required_tools", []))
    optional_tools = set(expected.get("optional_tools", []))
    actual_tools_set = set(actual_tools)

    # Check if all required tools were used
    missing_required = required_tools - actual_tools_set
    if missing_required:
        score -= 50
        issues.append(f"Missing required tools: {', '.join(missing_required)}")

    # Check for unnecessary tools (not in required or optional)
    allowed_tools = required_tools | optional_tools
    if allowed_tools:  # Only check if we have defined allowed tools
        unnecessary = actual_tools_set - \
            allowed_tools - {"search_knowledge_base"}
        if unnecessary:
            score -= 20
            issues.append(f"Unnecessary tools used: {', '.join(unnecessary)}")

    # Bonus for using helpful optional tools
    used_optional = actual_tools_set & optional_tools
    if used_optional:
        score = min(100, score + 10)
        issues.append(f"Good: Used optional tools: {', '.join(used_optional)}")

    return max(0, score), issues


def evaluate_response_content(response: str, expected: Dict) -> Tuple[float, List[str]]:
    """
    Evaluate if the response contains required information.

    Returns:
        Tuple of (score, list of issues)
    """
    issues = []
    score = 100.0
    response_lower = response.lower()

    # Check for required content elements
    must_include = expected.get("response_must_include", [])
    missing_elements = []

    for element in must_include:
        element_lower = element.lower()
        # Simple keyword matching - could be improved with NLP
        keywords = re.findall(r'\w+', element_lower)
        if len(keywords) > 0 and not any(keyword in response_lower for keyword in keywords[:3]):
            missing_elements.append(element)

    if missing_elements:
        penalty = (len(missing_elements) / len(must_include)) * \
            60 if must_include else 0
        score -= penalty
        issues.append(
            f"Missing required elements: {'; '.join(missing_elements[:3])}")

    # Check response length (too short might miss details, too long is inefficient)
    if len(response) < 50:
        score -= 20
        issues.append("Response too brief")
    elif len(response) > 2000:
        score -= 10
        issues.append("Response too verbose")

    # Check for ticket creation when required
    if "create_ticket" in expected.get("required_tools", []):
        if "ticket-" not in response.lower():
            score -= 20
            issues.append("No ticket number provided despite creating ticket")

    return max(0, score), issues


def evaluate_tone(response: str, expected: Dict, query: str) -> Tuple[float, List[str]]:
    """
    Evaluate if the response tone is appropriate.

    Returns:
        Tuple of (score, list of issues)
    """
    issues = []
    score = 100.0
    response_lower = response.lower()

    # Check for urgency acknowledgment
    if "urgent" in query.lower() or "immediately" in query.lower() or "asap" in query.lower():
        urgency_words = ["immediately", "right away", "urgent",
                         "quickly", "priority", "understand the urgency"]
        if not any(word in response_lower for word in urgency_words):
            score -= 30
            issues.append("Failed to acknowledge urgency")

    # Check for empathy in problem situations
    if any(word in query.lower() for word in ["frustrated", "angry", "upset", "problem", "issue", "not working"]):
        empathy_words = ["apologize", "sorry",
                         "understand", "frustrating", "inconvenience"]
        if not any(word in response_lower for word in empathy_words):
            score -= 20
            issues.append("Lacks empathy for customer's situation")

    # Check for professional greeting/closing
    if not any(greeting in response_lower[:100] for greeting in ["hello", "hi", "thank you", "thanks", "glad", "happy to"]):
        score -= 10
        issues.append("Missing professional greeting")

    return max(0, score), issues


def evaluate_single_response(test_result: Dict, answer_key_entry: Dict) -> Dict:
    """Evaluate a single response against the answer key."""

    tools_score, tools_issues = evaluate_tools_usage(
        test_result.get("tools_used", []),
        answer_key_entry["expected_behavior"]
    )

    content_score, content_issues = evaluate_response_content(
        test_result.get("response", ""),
        answer_key_entry["expected_behavior"]
    )

    tone_score, tone_issues = evaluate_tone(
        test_result.get("response", ""),
        answer_key_entry["expected_behavior"],
        test_result.get("query", "")
    )

    # Calculate overall score
    overall_score = (tools_score * 0.3 + content_score *
                     0.4 + tone_score * 0.3)

    return {
        "test_id": test_result.get("test_id"),
        "query": test_result.get("query", "")[:100] + "...",
        "scores": {
            "overall": round(overall_score, 1),
            "tools": round(tools_score, 1),
            "content": round(content_score, 1),
            "tone": round(tone_score, 1)
        },
        "issues": {
            "tools": tools_issues,
            "content": content_issues,
            "tone": tone_issues
        },
        "response_time": test_result.get("response_time", 0)
    }


def generate_report(evaluations: List[Dict], output_path: str = None):
    """Generate an evaluation report."""

    # Calculate summary statistics
    avg_overall = sum(e["scores"]["overall"]
                      for e in evaluations) / len(evaluations)
    avg_tools = sum(e["scores"]["tools"]
                    for e in evaluations) / len(evaluations)
    avg_content = sum(e["scores"]["content"]
                      for e in evaluations) / len(evaluations)
    avg_tone = sum(e["scores"]["tone"] for e in evaluations) / len(evaluations)
    avg_response_time = sum(e["response_time"]
                            for e in evaluations) / len(evaluations)

    report = {
        "metadata": {
            "evaluated_at": datetime.now().isoformat(),
            "total_tests": len(evaluations)
        },
        "summary": {
            "average_scores": {
                "overall": round(avg_overall, 1),
                "tools_usage": round(avg_tools, 1),
                "content_quality": round(avg_content, 1),
                "tone_appropriateness": round(avg_tone, 1)
            },
            "average_response_time": round(avg_response_time, 2),
            "grade": get_grade(avg_overall)
        },
        "detailed_results": evaluations,
        "recommendations": generate_recommendations(evaluations)
    }

    if output_path:
        with open(output_path, 'w') as f:
            json.dump(report, f, indent=2)

    return report


def get_grade(score: float) -> str:
    """Convert score to letter grade."""
    if score >= 90:
        return "A - Excellent"
    elif score >= 80:
        return "B - Good"
    elif score >= 70:
        return "C - Satisfactory"
    elif score >= 60:
        return "D - Needs Improvement"
    else:
        return "F - Poor"


def generate_recommendations(evaluations: List[Dict]) -> List[str]:
    """Generate recommendations based on evaluation results."""
    recommendations = []

    # Analyze common issues
    all_tool_issues = []
    all_content_issues = []
    all_tone_issues = []

    for eval in evaluations:
        all_tool_issues.extend(eval["issues"]["tools"])
        all_content_issues.extend(eval["issues"]["content"])
        all_tone_issues.extend(eval["issues"]["tone"])

    # Tool usage recommendations
    if any("Missing required tools" in issue for issue in all_tool_issues):
        recommendations.append(
            "🔧 Improve tool selection logic in prompts - agent is not using required tools")

    if any("Unnecessary tools" in issue for issue in all_tool_issues):
        recommendations.append(
            "🎯 Refine tool usage - agent is using tools when not needed")

    # Content recommendations
    if any("Missing required elements" in issue for issue in all_content_issues):
        recommendations.append(
            "📝 Enhance response completeness - agent is missing key information")

    if any("too brief" in issue.lower() for issue in all_content_issues):
        recommendations.append(
            "📏 Increase response detail - responses are too short")

    if any("too verbose" in issue.lower() for issue in all_content_issues):
        recommendations.append(
            "✂️ Improve conciseness - responses are unnecessarily long")

    # Tone recommendations
    if any("urgency" in issue.lower() for issue in all_tone_issues):
        recommendations.append(
            "⚡ Add urgency detection - agent should recognize and acknowledge time-sensitive requests")

    if any("empathy" in issue.lower() for issue in all_tone_issues):
        recommendations.append(
            "💝 Improve empathy - agent should be more understanding of customer frustrations")

    return recommendations if recommendations else ["✅ Agent is performing well overall!"]


def main():
    parser = argparse.ArgumentParser(
        description='Evaluate agent responses against answer key')
    parser.add_argument(
        'test_results',
        help='Path to test results JSON file (from generate_test_data.py)'
    )
    parser.add_argument(
        '--answer-key',
        default='answer_key.json',
        help='Path to answer key (default: answer_key.json)'
    )
    parser.add_argument(
        '--output',
        help='Output path for evaluation report'
    )
    parser.add_argument(
        '--verbose',
        action='store_true',
        help='Show detailed evaluation for each test'
    )

    args = parser.parse_args()

    print("🔍 Agent Response Evaluator")
    print("=" * 60)

    # Load data
    print(f"📚 Loading answer key from {args.answer_key}")
    answer_key = load_answer_key(args.answer_key)

    print(f"📊 Loading test results from {args.test_results}")
    test_results = load_test_results(args.test_results)

    # Evaluate each response
    evaluations = []
    print(f"\n⚡ Evaluating {len(test_results['results'])} responses...")

    for result in test_results['results']:
        test_id = result.get('test_id', '')

        # Find corresponding answer key entry
        answer_entry = None
        for conv in answer_key['conversations']:
            if conv['id'] == test_id:
                answer_entry = conv
                break

        if answer_entry:
            evaluation = evaluate_single_response(result, answer_entry)
            evaluations.append(evaluation)

            if args.verbose:
                print(
                    f"\n{test_id}: Overall Score = {evaluation['scores']['overall']}")
                print(
                    f"  Tools: {evaluation['scores']['tools']} | Content: {evaluation['scores']['content']} | Tone: {evaluation['scores']['tone']}")
                for category, issues in evaluation['issues'].items():
                    if issues:
                        print(
                            f"  {category.capitalize()} issues: {'; '.join(issues)}")

    # Generate report
    output_path = args.output or f"evaluation_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
    report = generate_report(evaluations, output_path)

    # Print summary
    print("\n" + "=" * 60)
    print("📈 EVALUATION SUMMARY")
    print("=" * 60)
    print(
        f"Overall Score: {report['summary']['average_scores']['overall']}/100")
    print(f"Grade: {report['summary']['grade']}")
    print(f"\nCategory Scores:")
    print(
        f"  🔧 Tool Usage: {report['summary']['average_scores']['tools_usage']}/100")
    print(
        f"  📝 Content Quality: {report['summary']['average_scores']['content_quality']}/100")
    print(
        f"  💬 Tone Appropriateness: {report['summary']['average_scores']['tone_appropriateness']}/100")
    print(
        f"\n⏱️ Average Response Time: {report['summary']['average_response_time']}s")

    print(f"\n💡 Recommendations:")
    for rec in report['recommendations']:
        print(f"  {rec}")

    print(f"\n✅ Evaluation report saved to: {output_path}")


if __name__ == "__main__":
    main()
